from typing import Anyimport discordfrom discord import Color, Embedfrom discord.ext import commandsfrom discord.ext.commands import Command, Context, CommandErrorfrom utils.EmbedGeneratorUtil import EmbedGeneratorclass CustomHelpCommand(commands.HelpCommand):    def get_command_signature(self, command: discord.ext.commands.core.Command = commands.Parameter(name="command", description="The command to get help information from.", kind=commands.Parameter.KEYWORD_ONLY)):        """        Gets the bot prefix, command name, and any command arguments needed.        :param command: This is the command we are calling, accessing data from the class of the command.        :return:        """        return '%s%s %s' % (self.context.clean_prefix, command.qualified_name, command.signature)    async def send_bot_help(self, mapping: dict = commands.Parameter(name="mapping", description="Parsing of all cogs, commands, and prefix/arguments", kind=commands.Parameter.KEYWORD_ONLY)):        """        Default 'help' embed that shows all cogs, with respected commands and info about arguments.        :param mapping: Maps the command information into a usable list format to display.        :return:        """        if mapping is None:            raise commands.MissingRequiredArgument(param=commands.Parameter('mapping', commands.Parameter.KEYWORD_ONLY, description="Parsing of all cogs, commands, and prefix/arguments."))        embed = Embed(title="Help", color=Color.blurple())        for cog, _cmds in mapping.items():            filtered = await self.filter_commands(_cmds, sort=True)            command_signatures = [self.get_command_signature(c) for c in filtered]            if command_signatures:                cog_name = getattr(cog, "qualified_name", "No Category")                embed.add_field(name=cog_name, value="\n".join(command_signatures), inline=False)        channel = self.get_destination()        await channel.send(embed=embed)    async def send_command_help(self, command: discord.ext.commands.core.Command = commands.Parameter(name="command", description="The command to get help information from.", kind=commands.Parameter.KEYWORD_ONLY)):        """        Sends the help/docstring information about the command from above.        :param command: Name of the command you would like to access information from.        :return:        """        embed = Embed(title=self.get_command_signature(command), color=Color.blurple())        if command.help:            embed.description = command.help        if alias := command.aliases:            embed.add_field(name='Aliases', value=", ".join(alias), inline=False)        channel = self.get_destination()        await channel.send(embed=embed)    async def send_error_message(self, error: str = commands.Parameter(name="error", description="The error message sent", kind=commands.Parameter.POSITIONAL_OR_KEYWORD), /) -> None:        """        Sends an error if there is any.        :param error: The error and the error class that was thrown.        :return:        """        embed = EmbedGenerator(self.context.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description=f"{error}", colour=Color.red(), timestamp=True)        await self.context.reply(embed=embed)